// Deterministic unit economics calculation engine.
// AI only ever supplies the raw assumptions below — every number in this
// file is computed with plain arithmetic, never generated by a model.

export const DEFAULT_ASSUMPTIONS = {
  companyName: "Company",
  arpu: 100,
  grossMargin: 0.75,
  monthlyChurn: 0.03,
  cac: 300,
  monthlyDiscountRate: 0.01,
  projectionMonths: 36,
  notes: "",
};

const num = (v, fallback) => (typeof v === "number" && Number.isFinite(v) ? v : fallback);

// Fills in anything missing/malformed from an AI-supplied assumptions object
// with the defaults above, so the engine always has a complete, well-typed input.
export function validateAssumptions(raw) {
  const a = raw && typeof raw === "object" ? raw : {};
  const projectionMonths = Math.round(num(a.projectionMonths, DEFAULT_ASSUMPTIONS.projectionMonths));

  return {
    companyName: typeof a.companyName === "string" && a.companyName.trim()
      ? a.companyName.trim()
      : DEFAULT_ASSUMPTIONS.companyName,
    arpu: num(a.arpu, DEFAULT_ASSUMPTIONS.arpu),
    grossMargin: num(a.grossMargin, DEFAULT_ASSUMPTIONS.grossMargin),
    monthlyChurn: Math.max(0, num(a.monthlyChurn, DEFAULT_ASSUMPTIONS.monthlyChurn)),
    cac: num(a.cac, DEFAULT_ASSUMPTIONS.cac),
    monthlyDiscountRate: num(a.monthlyDiscountRate, DEFAULT_ASSUMPTIONS.monthlyDiscountRate),
    projectionMonths: Math.max(1, Math.min(120, Number.isFinite(projectionMonths) ? projectionMonths : DEFAULT_ASSUMPTIONS.projectionMonths)),
    notes: typeof a.notes === "string" ? a.notes : "",
  };
}

// Computes lifetime value, LTV/CAC, CAC payback, and a month-by-month cohort
// table for a single customer. Zero churn is handled safely: an infinite
// lifetime has no closed-form LTV, so the "simple" LTV and the cohort table
// both fall back to the finite projection horizon instead of dividing by zero.
export function computeUnitEconomics(rawAssumptions) {
  const a = validateAssumptions(rawAssumptions);
  const grossProfitPerMonth = a.arpu * a.grossMargin;

  const avgLifetimeMonths = a.monthlyChurn > 0 ? 1 / a.monthlyChurn : null;
  const simpleLTV = a.monthlyChurn > 0
    ? grossProfitPerMonth / a.monthlyChurn
    : grossProfitPerMonth * a.projectionMonths;

  const months = [];
  let survival = 1;
  let cumulativeGrossProfit = 0;
  let discountedLTV = 0;
  let cacPaybackMonths = null;

  for (let m = 1; m <= a.projectionMonths; m++) {
    if (m > 1) survival = survival * (1 - a.monthlyChurn);
    const expectedGrossProfit = survival * grossProfitPerMonth;
    const previousCumulative = cumulativeGrossProfit;
    cumulativeGrossProfit += expectedGrossProfit;
    const discountedExpectedGrossProfit = expectedGrossProfit / Math.pow(1 + a.monthlyDiscountRate, m);
    discountedLTV += discountedExpectedGrossProfit;

    const paybackReached = cumulativeGrossProfit >= a.cac;
    if (cacPaybackMonths === null && paybackReached) {
      // Linear interpolation between the month before and the month of
      // crossing, for a fractional payback month rather than a coarse integer.
      const delta = cumulativeGrossProfit - previousCumulative;
      const frac = delta > 0 ? (a.cac - previousCumulative) / delta : 0;
      cacPaybackMonths = (m - 1) + frac;
    }

    months.push({
      month: m,
      survival,
      expectedGrossProfit,
      cumulativeGrossProfit,
      discountedExpectedGrossProfit,
      paybackReached,
    });
  }

  const ltvToCac = a.cac > 0 ? simpleLTV / a.cac : null;
  const discountedLtvToCac = a.cac > 0 ? discountedLTV / a.cac : null;

  return {
    assumptions: a,
    grossProfitPerMonth,
    avgLifetimeMonths,
    simpleLTV,
    discountedLTV,
    ltvToCac,
    discountedLtvToCac,
    cacPaybackMonths,
    months,
  };
}

// Builds a symmetric range of `count` values centered on `center`, step apart,
// clamped to a safe minimum so churn/CAC never go to zero or negative.
export function sensitivityRange(center, step, count = 5, min = 0.0001) {
  const half = Math.floor(count / 2);
  return Array.from({ length: count }, (_, i) => Math.max(min, center + (i - half) * step));
}

// 5x5 grid of LTV/CAC across monthly churn (rows) and CAC (columns).
export function computeSensitivity(rawAssumptions, opts = {}) {
  const a = validateAssumptions(rawAssumptions);
  const churnSteps = opts.churnSteps ?? sensitivityRange(a.monthlyChurn, Math.max(a.monthlyChurn * 0.3, 0.005), 5, 0.0001);
  const cacSteps = opts.cacSteps ?? sensitivityRange(a.cac, Math.max(a.cac * 0.25, 1), 5, 1);

  const grid = churnSteps.map((monthlyChurn) =>
    cacSteps.map((cac) => {
      if (cac <= 0) return { monthlyChurn, cac, error: true, ltvToCac: null };
      const result = computeUnitEconomics({ ...a, monthlyChurn, cac });
      return { monthlyChurn, cac, error: false, ltvToCac: result.ltvToCac };
    })
  );

  return { churnSteps, cacSteps, grid };
}
